// ── Bulk-add helper ─────────────────────────────────────────────────────────
// Author new translations one key at a time with all languages together, then
// distribute into STRINGS[lang][key]. Any language omitted for a key falls back
// to English automatically via t(). Order of langCodes matches the tuple order.
const LANG_ORDER = ['en','hi','bn','ta','te','mr','gu','kn','ml','or','pa','as','mni','kok','ne','ur'];
const addKeys = (entries) => {
  for (const [key, vals] of Object.entries(entries)) {
    LANG_ORDER.forEach((code, i) => {
      if (vals[i] == null) return;
      if (!STRINGS[code]) STRINGS[code] = {};
      STRINGS[code][key] = vals[i];
    });
  }
};

// Tuple order: [en, hi, bn, ta, te, mr, gu, kn, ml, or, pa, as, mni, kok, ne, ur]

